statement:
Two strings `a` and `b` of lowercase English letters are given. A single operation replaces one character of either string with any lowercase letter. Return the fewest operations after which **at least one** of these holds:

1. every letter of `a` comes strictly earlier in the alphabet than every letter of `b`;
2. every letter of `b` comes strictly earlier in the alphabet than every letter of `a`;
3. all characters of `a` and `b` together are one and the same letter.

validator:
function validate([a, b]) {
  for (const [name, s] of [['a', a], ['b', b]]) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return `${name} needs 1 to 10^5 characters.`;
    if (!/^[a-z]+$/.test(s)) return `${name} may contain only lowercase letters.`;
  }
  return null;
}

