function minCharacters(a, b) {
  const countA = new Array(26).fill(0);
  const countB = new Array(26).fill(0);
  for (const ch of a) countA[ch.charCodeAt(0) - 97]++;
  for (const ch of b) countB[ch.charCodeAt(0) - 97]++;

  const total = a.length + b.length;
  let best = total;
  for (let i = 0; i < 26; i++) {
    best = Math.min(best, total - countA[i] - countB[i]);
  }

  let prefixA = 0;
  let prefixB = 0;
  for (let i = 0; i < 25; i++) {
    prefixA += countA[i];
    prefixB += countB[i];
    best = Math.min(best, a.length - prefixA + prefixB);
    best = Math.min(best, b.length - prefixB + prefixA);
  }
  return best;
}

