function minCharacters(a, b) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  let answer = Infinity;
  for (const letter of letters) {
    let cost = 0;
    for (const ch of a + b) if (ch !== letter) cost++;
    answer = Math.min(answer, cost);
  }
  // Boundary t: the "small" string must use letters < t, the "big" one letters >= t.
  for (let t = 1; t < 26; t++) {
    const cut = letters[t];
    const costSplit = (small, big) => {
      let cost = 0;
      for (const ch of small) if (ch >= cut) cost++;
      for (const ch of big) if (ch < cut) cost++;
      return cost;
    };
    answer = Math.min(answer, costSplit(a, b), costSplit(b, a));
  }
  return answer;
}

