function generate(rand, size) {
  const word = (length) => {
    const low = Math.floor(rand() * 26);
    const high = low + Math.floor(rand() * (26 - low));
    let s = '';
    for (let i = 0; i < length; i++) s += String.fromCharCode(97 + low + Math.floor(rand() * (high - low + 1)));
    return s;
  };
  if (size === 'large') return [word(5000 + Math.floor(rand() * 5001)), word(5000 + Math.floor(rand() * 5001))];
  return [word(1 + Math.floor(rand() * 8)), word(1 + Math.floor(rand() * 8))];
}
